questionvariables.text:
/* 1 = symmetric facade about x = 0 ; 2 = building reflected in a lake (y = 0) */
cs : rand(2) + 1;
cH : if cs = 2 then 1 else 0;

if cs = 1 then (
    bbox : [-8, 8, 8, -8],
    shellL : [[0, 0], [-6, 0], [-6, 5], [0, 7]],
    wx : rand([-3, -2]), wy : rand([3, 4]),
    dx : rand([-1, -2]), dy : 1,
    parkW : [3, -3.5], parkD : [6, -3.5],
    intro : "The front (facade) of the building must be symmetric about its vertical centre line.",
    task : "Drag the Window and Door markers onto the empty right-hand side so that the facade is symmetric.",
    rulewords : "The facade is symmetric about the line \\(x = 0\\), so every point \\((x, y)\\) maps to \\((-x, y)\\).",
    mirrorword : "vertical centre line (x = 0)"
) else (
    bbox : [-8, 8, 8, -8],
    shellL : [[-5, 0], [5, 0], [5, 5], [0, 7], [-5, 5]],
    wx : rand([-3, -2]), wy : rand([3, 4]),
    dx : rand([1, 2]), dy : 1,
    parkW : [-6, 6.5], parkD : [6, 6.5],
    intro : "The building stands beside a calm lake and is reflected in the water. The waterline is the line of symmetry.",
    task : "Drag the Window and Door markers below the water so they show the correct reflection of the building.",
    rulewords : "The reflection is in the waterline \\(y = 0\\), so every point \\((x, y)\\) maps to \\((x, -y)\\).",
    mirrorword : "waterline (y = 0)"
);

WL : [wx, wy];
DL : [dx, dy];

/* triangular pediment above the door (drawn on the given side, then mirrored) */
TL : [[dx - 1, 2*dy], [dx + 1,2*dy], [dx, 2*dy + 1]];

/* reflection rule, and the wrong-line reflection used for diagnostics */
refl(p) := if cH = 1 then [p[1], -p[2]] else [-p[1], p[2]];
othr(p) := if cH = 1 then [-p[1], p[2]] else [p[1], -p[2]];

ta1 : refl(WL);
ta2 : refl(DL);
sameW : WL;      axisW : othr(WL);
sameD : DL;      axisD : othr(DL);

/* congruence dropdown: [value, correct?, displayed label] */
tac : random_permutation([
    ["yes",     true,  "Yes - it is congruent (same size and shape, just mirror-reversed)"],
    ["similar", false, "No - the reflected triangle is only similar, not congruent"],
    ["resized", false, "No - reflection changes the size of the triangle"]]);

feedbackvariables.text:
dc    : sqrt((ans1[1] - ta1[1])^2 + (ans1[2] - ta1[2])^2);
dsame : sqrt((ans1[1] - sameW[1])^2 + (ans1[2] - sameW[2])^2);
daxis : sqrt((ans1[1] - axisW[1])^2 + (ans1[2] - axisW[2])^2);

dc    : sqrt((ans2[1] - ta2[1])^2 + (ans2[2] - ta2[2])^2);
dsame : sqrt((ans2[1] - sameD[1])^2 + (ans2[2] - sameD[2])^2);
daxis : sqrt((ans2[1] - axisD[1])^2 + (ans2[2] - axisD[2])^2);
